using Xunit;using Nd30.DocumentEngine.Model;using Nd30.LegalValidator.Authorization;using Nd30.LegalValidator.Model;using Nd30.LegalValidator.Remediation;using Nd30.LegalValidator.State;namespace Nd30.LegalValidator.Tests;public sealed class V25L4CIntentTests{static DocumentIdentity D(char c='a')=>new("SHA-256",new string(c,64));static RuleIdentity R()=>new("RULE.1","SRC","loc");static PackageSafetyState S()=>new(true,false,false,false,false,false,false,[],PatchPolicy.NORMAL,[]);static ValidationResult F()=>new("RULE.1",ValidationStatus.FAIL,"LEGAL_ERROR",new("SRC","loc"),new("paragraph","title","alignment"),"center","left",[new("semantic_component_detection",EvidenceAuthority.Authoritative,"ev-1",1,false,new Dictionary<string,string>{{"target_id","p1"}})],[],[],"applicable",1,PatchEligibility.ELIGIBLE,"test");static RemediationProposal P()=>new RemediationPlanner().Propose(F(),S(),"paragraph_alignment",new(D(),R()));static ParagraphTargetLocator T(string id="p1")=>new("/word/document.xml","paragraph",id,id=="p1"?"body/p[1]":"body/p[2]",new string('b',64),"paragraph.alignment");[Fact]public void Deterministic(){var p=P();Assert.Equal(MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId,MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId);}[Fact]public void Target_changes_id(){var p=P();Assert.NotEqual(MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId,MutationIntent.Create(p,T("p2"),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId);}[Fact]public void Before_changes_id(){var p=P();Assert.NotEqual(MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId,MutationIntent.Create(p,T(),ParagraphAlignmentValue.RIGHT,ParagraphAlignmentValue.CENTER).MutationIntentId);}[Fact]public void After_changes_id(){var p=P();Assert.NotEqual(MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER).MutationIntentId,MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.RIGHT).MutationIntentId);}[Fact]public void Auth_A_rejects_B(){var p=P();var x=MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER);var y=MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.RIGHT);Assert.Equal(AuthorizationDecision.INTENT_MISMATCH,AuthorizationBoundary.Authorize(p,S(),AuthorizationArtifact.Issue(p,x),D(),R(),y).Decision);}[Fact]public void Request_carries_exact_after(){var p=P();var i=MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER);var q=AuthorizationBoundary.Authorize(p,S(),AuthorizationArtifact.Issue(p,i),D(),R(),i).Request!;Assert.Equal(ParagraphAlignmentValue.CENTER,q.Intent!.DesiredAfter);Assert.Equal(FormattingProvenance.DIRECT,q.Intent.ExpectedSource);}[Fact]public void State_mismatch_rejected(){var p=P();var i=MutationIntent.Create(p,T(),ParagraphAlignmentValue.LEFT,ParagraphAlignmentValue.CENTER);Assert.Equal(AuthorizationDecision.STALE_STATE,AuthorizationBoundary.Authorize(p,S(),AuthorizationArtifact.Issue(p,i),D('c'),R(),i).Decision);}}
